import { RangerClient } from '../../src/clients/ranger-client.js';
import { describe, expect, it } from 'vitest';

/**
 * VAL-DEMO-003 independent acceptance tests: they run against the ONE
 * integration generated by the initial real demo run, reached ONLY through
 * the public API (preview session + connection ticket) and the private
 * preview gateway. Real HTTP responses decide the result; no paid agent run
 * is involved here. Opt-in (RANGER_ACCEPTANCE_LIVE=1 + env), so the offline
 * e2e gate stays green. Evidence records statuses and codes only — the
 * connection ticket value never enters output.
 */

interface AcceptanceEnv {
  apiUrl: string;
  previewUrl: string;
  bearer: string;
  projectId: string;
  guestAppPort: number;
}

function readAcceptanceEnv(): AcceptanceEnv | null {
  if (process.env['RANGER_ACCEPTANCE_LIVE'] !== '1') return null;
  const apiUrl = process.env['RANGER_ACCEPTANCE_API_URL'];
  const previewUrl = process.env['RANGER_ACCEPTANCE_PREVIEW_URL'];
  const bearer = process.env['RANGER_ACCEPTANCE_BEARER'];
  const projectId = process.env['RANGER_ACCEPTANCE_PROJECT_ID'];
  if (apiUrl === undefined || previewUrl === undefined || bearer === undefined || projectId === undefined) {
    throw new Error('RANGER_ACCEPTANCE_LIVE=1 requires RANGER_ACCEPTANCE_API_URL, RANGER_ACCEPTANCE_PREVIEW_URL, RANGER_ACCEPTANCE_BEARER and RANGER_ACCEPTANCE_PROJECT_ID');
  }
  return {
    apiUrl,
    previewUrl,
    bearer,
    projectId,
    guestAppPort: Number(process.env['RANGER_ACCEPTANCE_GUEST_PORT'] ?? '8080'),
  };
}

const ACCEPTANCE_ENV = readAcceptanceEnv();

interface TicketResponse {
  status: 'drafted' | 'duplicate' | 'error';
  ticketId?: string;
  draft?: string;
  reason?: string;
  refund?: { refundId: string; status: string; receipt: string | null };
}

interface TicketRecord {
  ticketId: string;
  eventId: string;
  status: string;
  draft: string | null;
  audit: Array<{ op: string }>;
}

interface RefundRecord {
  refundId: string;
  status: 'pending_human_confirmation' | 'executed';
  receipt: string | null;
}

describe.skipIf(ACCEPTANCE_ENV === null)('generated integration acceptance (VAL-DEMO-003, public preview surface)', () => {
  const env = ACCEPTANCE_ENV!;
  let base = '';

  const postTicket = async (body: Record<string, string>): Promise<TicketResponse> => {
    const response = await fetch(`${base}/tickets`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(body),
    });
    expect(response.status, `POST /tickets ${body.eventId} failed`).toBe(200);
    return (await response.json()) as TicketResponse;
  };

  const getRecord = async (path: string): Promise<unknown> => {
    const response = await fetch(`${base}${path}`);
    expect(response.status, `GET ${path} failed`).toBe(200);
    return response.json();
  };

  const auditOf = async (eventId: string): Promise<TicketRecord> => (await getRecord(`/tickets/${eventId}`)) as TicketRecord;

  it('opens the private preview tunnel to the fixed guest app port through the public API', async () => {
    const client = new RangerClient({ baseUrl: env.apiUrl, headers: { authorization: `Bearer ${env.bearer}` } });
    const preview = await client.createPreviewSession({ path: { projectId: env.projectId }, body: { guestPort: env.guestAppPort } });
    const appTicket = await client.createConnectionTicket({ body: { projectId: env.projectId, purpose: 'app-preview' } });
    base = `${env.previewUrl}${preview.session.gatewayPath}?ticket=${encodeURIComponent(appTicket.ticket)}`;
    expect(base).toContain('/preview/sessions/');
    const health = await fetch(`${base}/health`);
    expect(health.status).toBe(200);
    expect(await health.json()).toMatchObject({ status: 'ok' });
  }, 30_000);

  it('drafts a policy-grounded reply for a normal ticket with one order lookup', async () => {
    const response = await postTicket({
      eventId: 'evt-acc-normal-1',
      orderId: 'ORD-1',
      subject: 'Where is my order?',
      message: 'Hi, my order has not arrived yet. Can you help?',
    });
    expect(response.status).toBe('drafted');
    expect(response.draft ?? '').toContain('30 days');
    const record = await auditOf('evt-acc-normal-1');
    expect(record.status).toBe('drafted');
    expect(record.audit.filter((entry) => entry.op === 'order_lookup')).toHaveLength(1);
  }, 30_000);

  it('processes a duplicate ticket event exactly once', async () => {
    const replay = await postTicket({
      eventId: 'evt-acc-normal-1',
      orderId: 'ORD-1',
      subject: 'Different body, same event id',
      message: 'A redelivery of the same inbox event.',
    });
    expect(replay.status).toBe('duplicate');
    expect(replay.ticketId).toBeTruthy();
    const record = await auditOf('evt-acc-normal-1');
    expect(record.audit.filter((entry) => entry.op === 'order_lookup')).toHaveLength(1);
  }, 30_000);

  it('handles a missing order without inventing data or drafting', async () => {
    const response = await postTicket({
      eventId: 'evt-acc-missing-1',
      orderId: 'ORD-MISSING',
      subject: 'Order question',
      message: 'Where is my order?',
    });
    expect(response.status).toBe('error');
    expect(response.reason).toBe('order_not_found');
    expect(response.draft).toBeUndefined();
    const record = await auditOf('evt-acc-missing-1');
    expect(record.draft).toBeNull();
  }, 30_000);

  it('returns a safe error on upstream order failure with no draft claiming success', async () => {
    const response = await postTicket({
      eventId: 'evt-acc-upstream-1',
      orderId: 'ORD-503',
      subject: 'Order question',
      message: 'Where is my order?',
    });
    expect(response.status).toBe('error');
    expect(response.reason).toBe('order_service_unavailable');
    expect(response.draft).toBeUndefined();
  }, 30_000);

  it('keeps refunds pending until explicit human confirmation, then executes once', async () => {
    const response = await postTicket({
      eventId: 'evt-acc-refund-1',
      orderId: 'ORD-1',
      subject: 'I want my money back',
      message: 'Please refund my order, it arrived damaged.',
    });
    expect(response.status).toBe('drafted');
    expect(response.refund?.refundId).toMatch(/^rf_/);
    expect(response.refund?.status).toBe('pending_human_confirmation');
    expect(response.refund?.receipt).toBeNull();

    // Before the human confirms: no refund executed.
    const before = (await getRecord(`/refunds/${response.refund!.refundId}`)) as RefundRecord;
    expect(before.status).toBe('pending_human_confirmation');
    expect(before.receipt).toBeNull();
    const beforeAudit = await auditOf('evt-acc-refund-1');
    expect(beforeAudit.audit.filter((entry) => entry.op === 'refund_execute')).toHaveLength(0);

    // The explicit human confirmation, then exactly one sandbox refund.
    const confirmed = await fetch(`${base}/refunds/${response.refund!.refundId}/confirm`, { method: 'POST' });
    expect(confirmed.status).toBe(200);
    const executed = (await confirmed.json()) as RefundRecord;
    expect(executed.status).toBe('executed');
    expect(executed.receipt ?? '').toMatch(/^rcpt_/);

    const after = (await getRecord(`/refunds/${response.refund!.refundId}`)) as RefundRecord;
    expect(after.status).toBe('executed');
    expect(after.receipt).toBe(executed.receipt);
    const afterAudit = await auditOf('evt-acc-refund-1');
    expect(afterAudit.audit.filter((entry) => entry.op === 'refund_execute')).toHaveLength(1);
  }, 30_000);
});
